style.css:
@-moz-document domain("google.com"), domain("www.google.com"), domain("encrypted.google.com") {
#hplogo, .lnXESd {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Google_logo_%282013-2015%29.svg/1024px-Google_logo_%282013-2015%29.svg.png") !important;
    background-size: contain !important; /* Ensures the image fits nicely */
    background-repeat: no-repeat !important; /* Prevents tiling */
    width: auto !important; /* Adjust width to fit the image */
    height: auto !important; /* Adjust height to fit the image */
    text-indent: -9999px !important; /* Hide the original text */
  }
  
   .logo.d-none.d-flex {
